*/
scwin.fnOrder = async function (mode, stat) {
    /* sdd-asis-lifecycle:begin fnOrder — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpName
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpName = async function () {
    /* sdd-asis-lifecycle:begin fnSearchCorpName — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("searchMode", "1");
    let val = $c.util.getComponent('AKCKwd').getValue(); if (val == null) { val = ''; }
    if (val !== "") {
        $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
        Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
} else {
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
    await scwin.fnSearchInit();
}
/* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpNameAllCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param items
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    /* sdd-asis-lifecycle:begin fnSearchCorpNameAllCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", '');
    if (items.length == 1) {
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", items[0].isurcd);
        await scwin.fnSearchCorpCode();
    } else {
        if (items.length > 1) {
            Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
    } else {
        await scwin.fnSearchCorpCode();
    }
}
/* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpCode
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpCode = async function () {
    /* sdd-asis-lifecycle:begin fnSearchCorpCode — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const repIsuSrtCd = ($c.util.getComponent("dma_fnDownloadReq").get("repIsuSrtCd") || '');
    if (repIsuSrtCd === "") {
        await $c.win.alert("조회한 회사명이 존재하지 않습니다. \n정확한 회사명을 입력해 주세요. \n회사명이 정확하지 않으시면 회사명 검색을 이용해주세요.");
        return;
    } else {
        await scwin.fnSearchInit();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCorpInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_isurCd kisComCd repIsuSrtCd comNm comAbbrv isurSymbl fssUnqNo
 * @returns
 * @hidden N
*/
scwin.setCorpInfo = function (ipt_isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    /* sdd-asis-lifecycle:begin setCorpInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let str = "";
    str += "isurCd : " + ipt_isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    if (repIsuSrtCd === "") {
        repIsuSrtCd = ipt_isurCd;
    }
    $c.util.getComponent('AKCKwd').setValue(comAbbrv);
    $c.util.getComponent("dma_fnDownloadReq").set("isurCd", ipt_isurCd);
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", repIsuSrtCd);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getToday
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getToday = function () {
    /* sdd-asis-lifecycle:begin getToday — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const date = new Date();
    const year = date.getFullYear();
    const month = ("0" + (1 + date.getMonth())).slice(-2);
    const day = ("0" + date.getDate()).slice(-2);
    return year + month + day;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.validateDate
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.validateDate = async function () {
    /* sdd-asis-lifecycle:begin validateDate — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frmDt = $c.util.getComponent('cal_fromDate').getValue();
    const toDt = $c.util.getComponent('cal_toDate').getValue();
    const today = scwin.getToday();
    const todayDash = today.substr(0, 4) + '-' + today.substr(4, 2) + '-' + today.substr(6, 2);
    if (frmDt.replace(/-/gi, '') < today || toDt.replace(/-/gi, '') < today) {
        await $c.win.alert("이전 날짜는 조회 할 수 없습니다.");
        if (frmDt.replace(/-/gi, '') < today) {
            $c.util.getComponent('cal_fromDate').setValue(todayDash);
        } else {
            if (toDt.replace(/-/gi, '') < today) {
                $c.util.getComponent('cal_toDate').setValue(todayDash);
            }
        }
        return false;
    } else {
        return true;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.closeDetail();
    const frmDt = $c.util.getComponent('cal_fromDate').getValue();
    const toDt = $c.util.getComponent('cal_toDate').getValue();
    if (!$c.date.isDate(frmDt)) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate(toDt)) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (!await scwin.validateDate()) {
        return;
    }
    if (($c.util.getComponent('cal_fromDate').getValue() == null ? '' : String($c.util.getComponent('cal_fromDate').getValue())) !== '' && ($c.util.getComponent('cal_toDate').getValue() == null ? '' : String($c.util.getComponent('cal_toDate').getValue())) !== '') {
        if (!($c.date.diffDate($c.util.getComponent('cal_fromDate').getValue(), $c.util.getComponent('cal_toDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
    if ($(document).find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchPrtdepoStatSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "prtdepoStat_sub");
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


